INSERT INTO blog_events(id,article_id,revision,action,actor,created_at) VALUES ('import-d0e052c41b60889c216be655e65afcf3','d0e052c41b60889c216be655e65afcf3',0,'imported','static-site-import','2026-10-04') ON CONFLICT(id) DO NOTHING;
INSERT INTO blog_articles(id,slug,title,summary,category,author,seo_title,description,image_url,image_alt,body_html,editorial_date,image_width,image_height,first_published_at,published_at,published_json,revision,published_revision,mutation_id,created_at,updated_at) VALUES ('89e2905a81aee16d1809e9219dd30d1f','vehicle-price-sheets-digital-qr-cards','Vehicle Price Sheets and QR Cards, Built From Your Inventory','Dealers are already using Postiqo''s price sheets and Digital Cards to put their existing inventory to work on the lot. Here is how the printed and digital parts fit together.','Product news','Postiqo Team','Vehicle Price Sheets and Digital QR Cards | Postiqo','Create vehicle price sheets from your inventory and link windshield QR codes to digital cards with photos, current details and dealership contacts.','https://postiqo.io/public/og-home.png?v=3','Postiqo - practical tools for vehicle listings and connected websites','<p>Your inventory already contains the facts buyers want: the vehicle, its photos, mileage, price and description. Postiqo now gives you more ways to use that information on the lot, with branded vehicle price sheets and Digital Cards that open from a windshield QR code.</p>
    <p>Dealership teams are already using these tools in their daily work. The purpose is practical: prepare vehicle information from the data you maintain, then make it easier for a visitor to take a closer look.</p>
    <h2>Branded price sheets without retyping every vehicle</h2>
    <p>The price sheet tools in <a href="https://postiqo.io/products/postiqo-publisher/">Postiqo Publisher</a> let you prepare vehicle documents from the inventory already in the app. Choose the design and the vehicles, preview a sheet, then export the selected vehicles to PDF for printing.</p>
    <p>You can start with the included design or import a DOCX template with your dealership&#x27;s logo, colours, layout and vehicle photos. Edit the template in Word or Google Docs, save it as DOCX and reuse it in Publisher.</p>
    <p>For a larger batch, you can select up to 200 vehicles. Each vehicle gets its own sheet, so the preparation happens as a batch instead of a separate copy-and-paste job for every car.</p>
    <p>Before exporting, check the preview with your actual inventory. Look at the vehicle identity, price, mileage, photos and dealership contacts. If a field is missing or incorrect, correct the source information before producing the final sheets.</p>
    <p>PDF generation uses a local document engine. Publisher can use an existing LibreOffice installation or the optional engine available through the app.</p>
    <h2>A windshield QR that opens the vehicle&#x27;s digital card</h2>
    <p><a href="https://postiqo.io/products/postiqo-cards/">Postiqo Digital Cards</a> gives a visitor another way to explore the same car. A QR code on the windshield opens a mobile vehicle page with the photos and details supplied by your inventory.</p>
    <p>The buyer can browse exterior and interior images, open the photos fullscreen, read the specifications and description, and use your published dealership contacts to call or email. The page opens in a browser with an internet connection, without a separate buyer app or account.</p>
    <p>This is useful when a vehicle is locked, a salesperson is with another customer or someone visits outside business hours. The visitor can see more of the vehicle and keep its link for a later conversation.</p>
    <p>You can explore the <a href="https://postiqo.io/products/postiqo-cards/demo/">sample vehicle card</a> to see the layout. It is a fictional demonstration with illustrative photos, not an advertised vehicle for sale.</p>
    <h2>What happens when the price changes?</h2>
    <p>Update the vehicle in your inventory and let the supported synchronization complete. The digital card can then show the updated price and details while the printed QR code stays the same.</p>
    <p>Keep the distinction between the link and the paper clear. A QR can continue to open an updated page, but a price printed on a physical sheet will remain as printed. Review and replace physical sheets when their information changes.</p>
    <p>The same care applies to availability. When synchronized inventory marks a vehicle inactive, its Postiqo card displays &quot;No longer listed&quot; and hides the asking price. Visitors can still contact the dealership to ask about current availability.</p>
    <h2>Set up the printed and digital parts together</h2>
    <p>A practical rollout starts with a few vehicles:</p>
    <ol><li>Check the inventory. Confirm the photos, details and dealership contacts you want buyers to see.</li><li>Preview the price sheets. Choose your design and inspect the output before printing a full batch.</li><li>Prepare the QR signs. Use Publisher&#x27;s QR documents to print a sign for each vehicle.</li><li>Scan from outside the car. Check that each windshield code is readable and opens the vehicle beside it.</li><li>Test the contact options. Confirm that the call and email links point to the right dealership contacts.</li><li>Keep a review routine. Check the digital page after supported inventory updates and replace any physical sheet whose printed details have changed.</li></ol>
    <p>This gives you a repeatable process for new arrivals as well as the vehicles already on your lot.</p>
    <h2>Enabling Digital Cards</h2>
    <p>Cards is included for a dealership with at least two active Publisher subscriptions. Ask Postiqo to enable it and confirm your inventory and public contact information. There are no additional Cards fees or commissions, and Cards is not sold separately.</p>
    <p>Whether you start with a branded price sheet or a QR-enabled vehicle page, the aim is the same: use the information you already maintain to help buyers understand the car in front of them. Explore the Publisher tools or contact us to check your dealership&#x27;s Cards setup.</p>','2026-10-04',1200,630,'2026-10-04','2026-10-04','{"slug":"vehicle-price-sheets-digital-qr-cards","title":"Vehicle Price Sheets and QR Cards, Built From Your Inventory","summary":"Dealers are already using Postiqo''s price sheets and Digital Cards to put their existing inventory to work on the lot. Here is how the printed and digital parts fit together.","category":"Product news","author":"Postiqo Team","seo_title":"Vehicle Price Sheets and Digital QR Cards | Postiqo","description":"Create vehicle price sheets from your inventory and link windshield QR codes to digital cards with photos, current details and dealership contacts.","image_url":"https://postiqo.io/public/og-home.png?v=3","image_alt":"Postiqo - practical tools for vehicle listings and connected websites","body_html":"<p>Your inventory already contains the facts buyers want: the vehicle, its photos, mileage, price and description. Postiqo now gives you more ways to use that information on the lot, with branded vehicle price sheets and Digital Cards that open from a windshield QR code.</p>\n    <p>Dealership teams are already using these tools in their daily work. The purpose is practical: prepare vehicle information from the data you maintain, then make it easier for a visitor to take a closer look.</p>\n    <h2>Branded price sheets without retyping every vehicle</h2>\n    <p>The price sheet tools in <a href=\"https://postiqo.io/products/postiqo-publisher/\">Postiqo Publisher</a> let you prepare vehicle documents from the inventory already in the app. Choose the design and the vehicles, preview a sheet, then export the selected vehicles to PDF for printing.</p>\n    <p>You can start with the included design or import a DOCX template with your dealership&#x27;s logo, colours, layout and vehicle photos. Edit the template in Word or Google Docs, save it as DOCX and reuse it in Publisher.</p>\n    <p>For a larger batch, you can select up to 200 vehicles. Each vehicle gets its own sheet, so the preparation happens as a batch instead of a separate copy-and-paste job for every car.</p>\n    <p>Before exporting, check the preview with your actual inventory. Look at the vehicle identity, price, mileage, photos and dealership contacts. If a field is missing or incorrect, correct the source information before producing the final sheets.</p>\n    <p>PDF generation uses a local document engine. Publisher can use an existing LibreOffice installation or the optional engine available through the app.</p>\n    <h2>A windshield QR that opens the vehicle&#x27;s digital card</h2>\n    <p><a href=\"https://postiqo.io/products/postiqo-cards/\">Postiqo Digital Cards</a> gives a visitor another way to explore the same car. A QR code on the windshield opens a mobile vehicle page with the photos and details supplied by your inventory.</p>\n    <p>The buyer can browse exterior and interior images, open the photos fullscreen, read the specifications and description, and use your published dealership contacts to call or email. The page opens in a browser with an internet connection, without a separate buyer app or account.</p>\n    <p>This is useful when a vehicle is locked, a salesperson is with another customer or someone visits outside business hours. The visitor can see more of the vehicle and keep its link for a later conversation.</p>\n    <p>You can explore the <a href=\"https://postiqo.io/products/postiqo-cards/demo/\">sample vehicle card</a> to see the layout. It is a fictional demonstration with illustrative photos, not an advertised vehicle for sale.</p>\n    <h2>What happens when the price changes?</h2>\n    <p>Update the vehicle in your inventory and let the supported synchronization complete. The digital card can then show the updated price and details while the printed QR code stays the same.</p>\n    <p>Keep the distinction between the link and the paper clear. A QR can continue to open an updated page, but a price printed on a physical sheet will remain as printed. Review and replace physical sheets when their information changes.</p>\n    <p>The same care applies to availability. When synchronized inventory marks a vehicle inactive, its Postiqo card displays &quot;No longer listed&quot; and hides the asking price. Visitors can still contact the dealership to ask about current availability.</p>\n    <h2>Set up the printed and digital parts together</h2>\n    <p>A practical rollout starts with a few vehicles:</p>\n    <ol><li>Check the inventory. Confirm the photos, details and dealership contacts you want buyers to see.</li><li>Preview the price sheets. Choose your design and inspect the output before printing a full batch.</li><li>Prepare the QR signs. Use Publisher&#x27;s QR documents to print a sign for each vehicle.</li><li>Scan from outside the car. Check that each windshield code is readable and opens the vehicle beside it.</li><li>Test the contact options. Confirm that the call and email links point to the right dealership contacts.</li><li>Keep a review routine. Check the digital page after supported inventory updates and replace any physical sheet whose printed details have changed.</li></ol>\n    <p>This gives you a repeatable process for new arrivals as well as the vehicles already on your lot.</p>\n    <h2>Enabling Digital Cards</h2>\n    <p>Cards is included for a dealership with at least two active Publisher subscriptions. Ask Postiqo to enable it and confirm your inventory and public contact information. There are no additional Cards fees or commissions, and Cards is not sold separately.</p>\n    <p>Whether you start with a branded price sheet or a QR-enabled vehicle page, the aim is the same: use the information you already maintain to help buyers understand the car in front of them. Explore the Publisher tools or contact us to check your dealership&#x27;s Cards setup.</p>","editorial_date":"2026-10-04","image_width":1200,"image_height":630,"date_published":"2026-10-04","date_modified":"2026-10-04"}',0,0,'import-89e2905a81aee16d1809e9219dd30d1f','2026-10-04','2026-10-04') ON CONFLICT(id) DO NOTHING;
